$entry='index-BFfiJ58u.js'
Test-Path "$root\dist\assets\$entry"
$f="$root\dist\assets\$entry"
foreach($p in '请选择收费类型','请输入收费标准','请选择机构名称','chargeType'){
  $q = Select-String -Path $f -Pattern $p -SimpleMatch -Quiet
  Write-Host "$p => $q"
}
