try { $r = Invoke-WebRequest 'http://127.0.0.1:8098/index.html' -UseBasicParsing -TimeoutSec 10; if($r.Content -match 'assets/(index-[A-Za-z0-9_-]+\.js)'){ Write-Host "entry=$($matches[1])" } } catch { Write-Host "ERR $_" }

