Write-Host "files containing 请选择收费类型:"
$hits | ForEach-Object { $_.Name }
Write-Host "--- also check 请输入收费标准 ---"
$all | Where-Object { (Select-String -Path $_.FullName -Pattern '请输入收费标准' -SimpleMatch -Quiet) } | ForEach-Object { $_.Name }

